entries[377422] = { ["name"] = "Quälende Schmerzen", ["text"] = "Disziplin, Heilig\n'Schattenwort: Schmerz' verursacht zusätzlich 3% Schaden. Wenn ein Gegner stirbt, während er von Eurem 'Schattenwort: Schmerz' betroffen ist, erhaltet Ihr 0.5% Mana.\n\nSchatten\n'Schattenwort: Schmerz' verursacht zusätzlich 3% Schaden. Wenn ein Gegner stirbt, während er von Eurem 'Schattenwort: Schmerz' betroffen ist, erhaltet Ihr 3 Wahnsinn." }
