entries[377441] = { ["name"] = "Luft-Crescendo", ["text"] = "Wirken in 2 sek.\nDathrea beschwört einen heftigen Luftstrom herauf, der nach außen vordringt und getroffenen Spielercharakteren 35 Naturschaden zufügt.\n\nGetroffene Spielercharaktere werden mit ' Verweilendes Schlitzen ' belegt." }
