entries[377447] = { ["name"] = "Flammenblitz", ["text"] = "50 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Flammenblitz auf das Ziel, der 0 Feuerschaden verursacht." }
entries[377449] = { ["name"] = "Flammendekoration", ["text"] = "Sofort 2 min Abklingzeit\nStampft auf den Boden und lasst Flammen von Eurer Position ausstrahlen. Diese verursachen 1690 Feuerschaden, der auf alle getroffenen Gegner aufgeteilt wird, und gewähren Euch für 30 Sek. einen Schild in Höhe von 3155 . Nach einer Verzögerung kehren die Flammen zurück, verursachen den gleichen Schaden erneut und frischen den Schild auf.\n\nSchaden und Absorption werden für jeden getroffenen Gegner bis maximal 5 Gegner erhöht." }
entries[377450] = { ["name"] = "Herbeigezauberte Frostkugel" }
entries[377451] = { ["name"] = "Herbeigezauberte Frostkugel", ["text"] = "40 Meter Reichweite\nSofort\nWenn Euer Mana über 65% ist, wird die Frostkugel auf Euer Ziel geworfen und verursacht 3041 Frostschaden.\n\nWenn Euer Mana unter 65% ist, trinkt Ihr stattdessen von der Frostkugel, um sofort 562 Mana wiederherzustellen." }
entries[377452] = { ["name"] = "Flüsterndes Symbol der Inkarnation", ["text"] = "Gebt Euch dem Flüstern des Symbols hin und werdet mit Frost erfüllt, was Euren kritischen Trefferwert um 57 erhöht.\n\nWenn Ihr an der Seite von Verbündeten kämpft, die mit Erde oder Feuer erfüllt sind, besteht eine Chance, dass Ihr 12 Sek. lang 16 des Werts ihrer jeweiligen Infusion erhaltet.\n\nDie Infusion ist von Eurer aktuellen Spezialisierung abhängig.\n(1.5s Abklingzeit)" }
entries[377453] = { ["name"] = "Segen der Sturmfresserin", ["text"] = "Sofort 3 min Abklingzeit\nNehmt den Sturm an und werdet für 10 Sek. zu einem unbeweglichen Urluftelementar.\n\nIn dieser Gestalt fügen die Winde um Euch allen Gegnern innerhalb von 10 Metern pro Sekunde 311 Naturschaden zu, der sich pro Sekunde um 10% erhöht, bis die Verwandlung endet." }
entries[377454] = { ["name"] = "Rasselnder Rubin", ["text"] = "Ca. 5 Procs pro Minute\nEure Angriffe bauen langsam Stapel von 'Erschütternde Kraft' auf, die Euch pro Stapel 3 Angriffskraft gewähren.\n\nBei 10 Stapeln entfesseln Eure nächsten 3 Nahkampffähigkeiten eine Schockwelle vor Euch, die allen Gegnern in einer Linie zusätzlich 903 Naturschaden zufügt. Die Schockwellen fügen Gegnern mit hoher Gesundheit mehr Schaden zu.\n(500ms Abklingzeit)" }
entries[377455] = { ["name"] = "Eisbluttodesfessel", ["text"] = "45 Meter Reichweite\nSofort 2 min Abklingzeit\nFügt Eurem Ziel 2197 Frostschaden zu und wickelt es sowie Gegner in der Nähe für 15 Sek. in ein Kristallnetz. Im Netz gefangene Gegner sind um 15% verlangsamt und erleiden 174 Frostschaden, wenn ein Gegner im Netz getroffen wird.\n\nDer Schaden erhöht sich für jeden im Netz gefangenen Gegner, bis zu 5 Gegner. Der Schaden pro Ziel ist bei mehr als 5 Gegnern verringert." }
entries[377456] = { ["name"] = "Weg der kontrollierten Strömungen", ["text"] = "Eure kritischen Treffer haben eine Chance, 'Statische Elektrizität' aufzubauen, was Euer Angriffstempo pro Stapel um 2% erhöht. Dieser Effekt kann einmal alle 1 Sek. auftreten.\n\nBei 10 Stapeln fährt ein Blitz durch Euch, der Eure Bewegungsgeschwindigkeit für 12 Sek. um 30% erhöht. Während Ihr vom Blitz ergriffen seid, schocken Eure automatischen Angriffe Euer Ziel und 1 weiteren Gegner in der Nähe und fügen ihnen 319 Naturschaden zu.\n\nWenn dieser Effekt nachlässt, werdet Ihr für 1 Min. geerdet und könnt nicht erneut 'Statische Elektrizität' aufbauen.\n(1.5s Abklingzeit)" }
entries[377457] = { ["name"] = "Alltotem des Meisters", ["text"] = "Nehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\nDieser Effekt kann nur einmal alle 30 Sek. auftreten.\n(30s Abklingzeit)" }
entries[377458] = { ["name"] = "Elementarhaltung: Erde", ["text"] = "100 Meter Reichweite\nSofort\nNehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\nDieser Effekt kann nur einmal alle 30 Sek. auftreten." }
entries[377459] = { ["name"] = "Elementarhaltung: Feuer", ["text"] = "100 Meter Reichweite\nSofort\nNehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\nDieser Effekt kann nur einmal alle 30 Sek. auftreten." }
entries[377461] = { ["name"] = "Elementarhaltung: Luft", ["text"] = "100 Meter Reichweite\nSofort\nNehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\nDieser Effekt kann nur einmal alle 30 Sek. auftreten." }
entries[377462] = { ["name"] = "Versprechen der Bruthüterin", ["text"] = "100 Meter Reichweite\nWirken in 1 sek. 5 sek. Abklingzeit\nWählt einen Spielercharakter aus, mit dem Ihr eine Bindung eingehen möchtet, und werdet für 1 Stunde zu seinem Wächter.\n\nWährend Ihr verbunden seid, erhaltet Ihr und Euer Verbündeter [Quellwert] Vielseitigkeit und stellt pro Sekunde [Quellwert] Gesundheit wieder her. Solange Ihr Euch innerhalb von 15 Metern zueinander aufhaltet, werden diese Boni erhöht.\n\nGilt nur für Heilerspezialisierungen.", ["unresolvedValues"] = true }
entries[377463] = { ["name"] = "Manische Trauerfackel", ["text"] = "40 Meter ReichweiteKanalisiert (Wirken in 2 sek.) 2 min Abklingzeit\nKanalisiert für 2 Sek. und entfesselt eine wilde Salve aus Flammen um Euer Ziel herum, die ihm bis zu [ 951 * (8) * (1 + Vielseitigkeit)] Feuerschaden zufügt und eine Chance hat, zusätzlich Gegnern in der Nähe Schaden zuzufügen.\n\nDurch den Tod eines verbündeten Spielercharakters wird die Abklingzeit um 90 Sek. verringert." }
entries[377464] = { ["name"] = "Verzweifelte Herbeirufung", ["text"] = "45 Meter Reichweite\nSofort 4 min Abklingzeit\nEntfesselt gefährliche Blitze und fügt Eurem Ziel 5877 Naturschaden und Euch 31 Naturschaden zu. Der Euch selbst zugefügte Schaden wird durch Stapel von Hass erhöht." }
entries[377465] = { ["name"] = "Verzweifelte Herbeirufung", ["text"] = "Das Wirken von Zaubern gewährt Stapel von Hass, durch die die Abklingzeit dieses Schmuckstücks bis zum Ende des Kampfes um 1 Sek. verringert wird. Dieser Effekt ist bis zu 180-mal stapelbar.\n(1s Abklingzeit)" }
entries[377466] = { ["name"] = "Boshafter Sturm", ["text"] = "Der Einsatz von Zaubern und Fähigkeiten erzeugt Stapel von Bosheit. Bei 5 Stapeln springt ein 'Boshafter Sturmblitz' auf Eurer anvisiertes Ziel über und verursacht im Verlauf von 3 Sek. [ 86 * (6) * (1 + Vielseitigkeit)] Naturschaden.\n\nBei Ablauf kehrt der Blitz zurück, erhöht die benötigten Stapel von Bosheit um 1 und erhöht den dem Ziel durch 'Boshafter Sturmblitz' zugefügten Schaden permanent, bis einer von Euch stirbt.\n(1s Abklingzeit)" }
entries[377467] = { ["name"] = "Fulminante Ladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nRaszageth lädt Ziele mit Elektrizität auf3 Sek. lang bewegungsunfähig . Bei Ablauf entlädt sich die Aufladung, fügt allen Spielercharakteren im Effektbereich 88328 Naturschaden zu und springt auf den nächsten getroffenen Spielercharakter über.\n\nJedes Mal, wenn ' Fulminante Ladung ' auf einen neuen Spielercharakter überspringt, verringert sich der Radius und der vorherige Spielercharakter wird mit ' Verbleibende Ladung ' belegt." }
