entries[377505] = { ["name"] = "Rasende Verwüstung", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nWährend er die Kammer mit ' Resonierende Nachwirkung ' füllt, beginnt Terros, verheerende Wellen an irdener Energie auszusenden, die 60063 Naturschaden verursachen und den durch ' Rasende Verwüstung ' erlittenen Schaden um 50% erhöhen." }
