entries[377858] = { ["name"] = "Erhitzte Schwünge", ["text"] = "100 Meter Reichweite\nSofort\nDer Schmiedemeister führt zwei Schwünge gegen sein aktuelles Ziel aus, die jeweils 9697798 körperlichen Schaden verursachen, und stößt das Ziel weg.\n\nDann springt er zur Position des Ziels und lässt seinen entzündeten Hammer niederkrachen, der Spielercharakteren innerhalb von 8 Metern um den Einschlag 24237972 körperlichen sowie 8475657 Feuerschaden zufügt." }
