entries[378757] = { ["name"] = "Aufspießen", ["text"] = "10 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nFügt Gegnern in einem kegelförmigen Bereich vor dem Zaubernden körperlichen Schaden zu und verringert ihre erhaltene Heilung 10 Sek. lang um 30%." }
