entries[378769] = { ["name"] = "Verbesserter Todesstoß", ["text"] = "Euer 'Gezielter Schuss' hat jetzt eine Chance von 15% und 'Schnellfeuer' eine Chance von 25%, 'Todesstoß' zu gewähren.\n\nDer kritische Schaden von 'Tödlicher Schuss' ist um 25% erhöht.\n\nTodesstoß\nDie Abklingzeit von 'Tödlicher Schuss' wird abgeschlossen. Euer nächster Einsatz von 'Tödlicher Schuss' kann gegen jedes Ziel unabhängig von seiner aktuellen Gesundheit eingesetzt werden." }
